def keep_single_blocks(grid, n_rows=22):
    result = [grid[0][:] for _ in range(n_rows)]
    color_counts = {}
    for i, row in enumerate(grid):
        if any(row):
            color = next(iter(row))
            color_counts[color] = color_counts.get(color, 0) + 1

    for i, row in enumerate(grid):
        if any(row):
            color = next(iter(row))
            if color_counts[color] == 1:
                result[i] = row

    return result

